import * as THREE from 'three/webgpu';
import { texture, uv, vec2, mul, add, normal, positionLocal, ThreeUniformNode } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { position, rotation, scale, colors } = config;
  const imageTex = ctx.textureLoader.load('/prism-mock/home/nodes/parallax-stack.png');
  const depthTex = ctx.textureLoader.load('/prism-mock/home/nodes/parallax-stack.depth.png');

  // Determine plane dimensions from texture aspect ratio (512x320)
  const img = imageTex.image;
  const aspect = img.width / img.height;
  const width = 2.5; // scene units
  const height = width / aspect;

  const geometry = new THREE.PlaneGeometry(width, height, 64, 64);

  // TSL uniform for mouse-driven UV offset
  const mouseOffset = new ThreeUniformNode(new THREE.Vector2(0, 0));

  // Build displacement and color nodes
  const uvs = uv(geometry);
  const offsetUv = uvs.add(vec2(mouseOffset.x, mouseOffset.y));
  const depthVal = texture(depthTex, offsetUv).r;
  const displacement = depthVal.mul(0.1);
  const positionNode = positionLocal.add(normal.mul(displacement));

  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = texture(imageTex, offsetUv);
  material.positionNode = positionNode;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(position.x, position.y, position.z);
  mesh.rotation.set(rotation.x, rotation.y, rotation.z);
  mesh.scale.set(scale.x, scale.y, scale.z);

  // Interaction handlers (hover rise, click press, parallax pointer move)
  mesh.userData.handlers = {
    pointerenter: () => {
      gsap.to(mesh.position, {
        y: position.y + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });
    },
    pointerleave: () => {
      gsap.to(mesh.position, {
        y: position.y,
        duration: 0.7,
        ease: 'power3.out',
      });
    },
    pointerdown: () => {
      gsap.to(mesh.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out',
      });
    },
    pointerup: () => {
      gsap.to(mesh.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.12,
        ease: 'back.out',
      });
    },
    pointermove: (e) => {
      // Subtle parallax offset based on intersection UV
      const x = (e.intersection.uv.x * 2 - 1) * 0.02;
      const y = (e.intersection.uv.y * 2 - 1) * 0.02;
      mouseOffset.value.set(x, y);
    },
    click: () => {
      mesh.dispatchEvent(new CustomEvent('hub-features.select'));
    },
  };

  // Cleanup: dispose resources and kill GSAP tweens
  mesh.userData.cleanup = () => {
    gsap.killTweensOf(mesh.position);
    gsap.killTweensOf(mesh.scale);
    geometry.dispose();
    material.dispose();
    imageTex.dispose();
    depthTex.dispose();
  };

  return mesh;
}
